<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Box, RefreshCw, Settings2, ShieldCheck, Clock, ArrowRight, X } from './ui/icon';
import { Sparkles } from 'lucide-vue-next';
import { api } from '../api';
import { Button } from './ui/button';
import { PageHeader } from './ui/page-header';
import { SearchInput } from './ui/controls';
import { ConfirmationDialog } from './ui/feedback';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from './ui/dialog';
import { runtimeRequest, type RuntimeEnvironment, type CpuResources } from './runtime/runtimeApi';
import { preparationReasons, criuStates } from './runtime/environmentLabels';
import EnvironmentResources from './runtime/EnvironmentResources.vue';
import ExecutionNodeBadge from './runtime/ExecutionNodeBadge.vue';
import PlatformBadge from './PlatformBadge.vue';
import EnvironmentKernel from './runtime/EnvironmentKernel.vue';
import RunWindowForm from './runtime/RunWindowForm.vue';
import '../native-environment.css';

const props=defineProps<{workspaceTaskAccountId?:number}>();
const emit=defineEmits<{close:[]}>();
const route=useRoute(),router=useRouter();
const rows=ref<RuntimeEnvironment[]>([]),query=ref(''),filter=ref('all'),error=ref(''),loading=ref(true),connected=ref(false);
const selectedId=ref<string|null>(null),activeTab=ref('overview'),visited=ref(new Set(['overview']));
const selected=computed(()=>rows.value.find(row=>row.environment_id===selectedId.value));
const pending=reactive(new Set<string>()),feedback=reactive(new Map<string,string>()),cpu=reactive(new Map<string,CpuResources>());
const cpuErrors=reactive(new Map<string,string>());
const editorBusy=ref(false),confirmation=ref<{id:string;operation:string;name:string}|null>(null),confirmError=ref('');
const tabs=[{id:'overview',title:'运行概览',note:'当前环境状态与运行组件',icon:Box},{id:'resources',title:'资源与采集',note:'在这里调整额度、内容采集与加速设置',icon:Settings2},{id:'kernel',title:'请求内核',note:'查看平台内置内核版本与运行状态',icon:Sparkles},{id:'schedule',title:'运行时段',note:'按账号当地时间安排工作窗口',icon:Clock},{id:'maintenance',title:'维护操作',note:'选择操作后确认影响，当前环境信息持续保留',icon:ShieldCheck}];
const states:Record<string,string>={ready:'就绪',stopped:'已停止',starting:'启动中',node_unreachable:'节点待核对',reconcile:'待对账',cli_reconcile:'CLI 待对账',profile_reauth:'画像授权中',profile_reauth_reconcile:'画像待对账'};
const roleNames=[{id:'cli',label:'CLI'},{id:'sender',label:'发送器'},{id:'network',label:'网络'}] as const;
const roles:Record<string,string>={running:'运行中',exited:'已退出',stopped:'已停止',created:'已创建',restarting:'重启中',missing:'未创建'};
const prepNames:Record<string,string>={ready:'热进程就绪',busy:'进程使用中',preparing:'正在准备',unprepared:'等待准备',sleeping:'环境休眠',disabled:'账号停用',maintenance:'维护中',failed:'准备失败',unknown:'待检查'};
const maintenance=[{id:'stop',label:'停止环境',note:'暂停该环境的运行，保留持久数据'},{id:'rebuild',label:'重建容器',note:'保留账号数据并重新准备运行容器'},{id:'reconcile',label:'故障对账',note:'核对服务端操作与环境状态'},{id:'reprofile',label:'校正画像',note:'按服务端许可更新环境画像'}];
const counts=computed(()=>[{id:'all',label:'全部环境',count:rows.value.length},{id:'ready',label:'就绪',count:rows.value.filter(row=>row.state==='ready').length},{id:'attention',label:'需要关注',count:rows.value.filter(row=>!['ready','stopped'].includes(row.state)).length},{id:'stopped',label:'已停止',count:rows.value.filter(row=>row.state==='stopped').length}]);
const filtered=computed(()=>rows.value.filter(row=>(!route.query.environment||row.environment_id===route.query.environment)&&(!route.query.gateway_account||String(row.gateway_account_id)===route.query.gateway_account)&&(filter.value==='all'||(filter.value==='attention'?!['ready','stopped'].includes(row.state):row.state===filter.value))&&`${row.name} ${row.environment_id}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())));
let alive=true,generation=0,controller:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,openedLocation='';
/** 显示真实未知状态，保留服务端原值。@param row 环境。@return 中文状态。 */
function stateLabel(row:RuntimeEnvironment):string{return states[row.state]??`未知状态：${row.state||'未提供'}`;}
/** 现场观察与已保存节点分别解释。@param row 环境。@return 观察说明。 */
function nodeStatus(row:RuntimeEnvironment):string{
 if(row.node&&!row.node.enabled)return'节点已暂停接单';
 if(row.node_message)return row.node_message;
 return row.node_observed===true?'现场已观测':'现场状态未观测';
}
/** 使用同一套卡片状态色。@param row 环境。@return 色彩类。 */
function tone(row:RuntimeEnvironment):string{return row.state==='ready'?'healthy':row.state==='stopped'?'muted':'warning';}
/** 当前已生效的开关状态。@param value 状态。@return 文案。 */
function featureLabel(value:RuntimeEnvironment['criu']):string{return value?.applied===true?(value.enabled?'已开启':'已关闭'):value?.applied===false?'待应用':'待核对';}
/** 区分首轮快照、真实失败及过期结果。@param row 环境。@return 当前准备状态。 */
function preparationLabel(row:RuntimeEnvironment):string{if(row.platform==='antigravity'){if(row.agy_runtime?.tool_waiting)return'等待工具结果';return ({ready:'进程就绪',busy:'执行中',unprepared:'等待首次请求',sleeping:'环境休眠',unknown:'状态待核对'} as Record<string,string>)[row.agy_runtime?.state??'unknown']||'状态待核对';}const value=row.native_preparation;if(!value)return'准备状态待核对';if(value.state==='unknown'){if(['snapshot_pending','snapshot_missing'].includes(value.reason??''))return value.checking?'正在检查':'等待快照';if(value.reason==='check_expired')return'检查已过期';return'状态待核对';}return prepNames[value.state]||'未知状态';}
/** 自动读取三角色实际额度，最多并行三个环境，回执归属当前列表代次。@param value 环境列表。@param current 页面请求代次。@param signal 本轮取消信号。@return 摘要读取结束。 */
async function loadCpu(value:RuntimeEnvironment[],current:number,signal:AbortSignal):Promise<void>{
 const targets=value.filter(row=>row.isolation_version===2&&!row.login_draft),ids=new Set(targets.map(row=>row.environment_id));
 for(const id of cpu.keys())if(!ids.has(id))cpu.delete(id);
 for(const id of cpuErrors.keys())if(!ids.has(id))cpuErrors.delete(id);
 for(const row of targets){if(cpu.get(row.environment_id)?.generation!==row.generation)cpu.delete(row.environment_id);cpuErrors.delete(row.environment_id);}
 let next=0;
 await Promise.all(Array.from({length:Math.min(3,targets.length)},async()=>{
  while(alive&&current===generation&&!signal.aborted){
   const row=targets[next++];if(!row)return;
   const id=row.environment_id,previous=cpu.get(id);
   try{
    const result=await runtimeRequest<CpuResources>(`/environments/${id}/cpu-resources`,{signal});
    // 资源表单可能在自动读取期间保存，同代次的新回执也需要保留。
    if(!alive||current!==generation||signal.aborted||cpu.get(id)!==previous)continue;
    if(result.generation!==row.generation)throw new Error('环境代次已变化，请刷新核对');
    cpu.set(id,result);cpuErrors.delete(id);
   }catch(cause){
    if(alive&&current===generation&&!signal.aborted&&cpu.get(id)===previous){cpu.delete(id);cpuErrors.set(id,(cause as Error).message);}
   }
  }
 }));
}
/** 配额展示区分实际数值、读取状态及能力缺失。@param row 当前环境。@param role 固定角色。@return 配额或中文读取状态。 */
function cpuLabel(row:RuntimeEnvironment,role:'cli'|'sender'|'network'):number|string{
 const value=cpu.get(row.environment_id);
 if(value?.generation===row.generation)return value.cpus[role];
 return row.isolation_version!==2?'未提供':cpuErrors.has(row.environment_id)?'读取失败':'读取中';
}
/** 编辑器回填实际额度，保持当前环境代次一致。@param id 环境ID。@param value 编辑器回执。@return 无。 */
function acceptCpu(id:string,value:CpuResources):void{if(!alive||rows.value.find(row=>row.environment_id===id)?.generation!==value.generation)return;cpu.set(id,value);cpuErrors.delete(id);}
/** 读请求串行拥有页面代次，关闭页面后释放轮询。@return 加载结束。 */
async function load():Promise<void>{if(!connected.value||!alive)return;clearTimeout(timer);controller?.abort();controller=new AbortController();const current=++generation,signal=controller.signal;loading.value=true;error.value='';try{const value=await runtimeRequest<RuntimeEnvironment[]>('/environments',{signal});if(!alive||current!==generation)return;rows.value=value;void loadCpu(value,current,signal);if(selectedId.value&&!selected.value)selectedId.value=null;openLinked();}catch(cause){if(alive&&current===generation&&!signal.aborted)error.value=(cause as Error).message;}finally{if(alive&&current===generation){loading.value=false;if(!document.hidden){const quick=editorBusy.value||pending.size||rows.value.some(row=>row.native_preparation?.checking||row.native_preparation?.state==='preparing'||row.native_preparation?.reason==='backend_pending');timer=setTimeout(load,quick?2000:20000);}}}}
/** 建立已有同源会话后再读取环境。@return 连接结束。 */
async function connect():Promise<void>{error.value='';loading.value=true;try{await api.openRuntime();if(!alive)return;connected.value=true;await load();}catch(cause){if(alive){error.value=(cause as Error).message;loading.value=false;}}}
/** 打开单一Vue工作区，切换分区保留已访问表单。@param row 环境。@param tab 分区。@return 无。 */
function open(row:RuntimeEnvironment,tab='overview'):void{selectedId.value=row.environment_id;activeTab.value=tab;visited.value=new Set([tab]);editorBusy.value=false;}
/** 深链接由顶层路由解释，不创建子文档历史。@return 无。 */
function openLinked():void{if(props.workspaceTaskAccountId){const key=`task:${props.workspaceTaskAccountId}`;if(openedLocation===key)return;const row=rows.value.find(item=>item.account_id===props.workspaceTaskAccountId);if(row){openedLocation=key;open(row,'schedule');}else error.value='当前任务账号的环境暂不可读取，请刷新后重试。';return;}if(openedLocation===route.fullPath)return;const tab=String(route.query.section??'');if(!tabs.some(item=>item.id===tab))return;const row=rows.value.find(item=>route.query.environment?item.environment_id===route.query.environment:route.query.gateway_account&&String(item.gateway_account_id)===route.query.gateway_account);if(row){openedLocation=route.fullPath;open(row,tab);}}
/** 关闭工作区，保存中的事务保留当前承载。@param value 新状态。@return 无。 */
function setOpen(value:boolean):void{if(!value&&!editorBusy.value){selectedId.value=null;if(props.workspaceTaskAccountId)emit('close');}}
/** 已访问分区持续挂载，防止轮询或切区清空输入。@param tab 目标分区。@return 无。 */
function chooseTab(tab:string):void{activeTab.value=tab;visited.value.add(tab);}
/** 执行用户明确选择的维护动作，使用原环境身份。@param id 环境ID。@param operation 原操作。@return 操作完成。 */
async function perform(id:string,operation:string):Promise<void>{if(pending.has(id))return;const original=rows.value.find(row=>row.environment_id===id);if(!original)return;const expectedGeneration=original.generation;pending.add(id);feedback.delete(id);confirmError.value='';try{await runtimeRequest(`/environments/${id}/${operation==='physical'?'physical-features/refresh':operation==='prepare'?'native-preparation':'maintenance'}`,{method:'POST',body:['physical','prepare'].includes(operation)?{}:{operation,expected_generation:expectedGeneration}});if(!alive)return;if(rows.value.find(row=>row.environment_id===id)?.generation!==expectedGeneration){if(confirmation.value?.id===id&&confirmation.value.operation===operation)confirmation.value=null;return;}feedback.set(id,operation==='physical'?'实测已刷新。':operation==='prepare'?'已安排后台原生准备。':'维护操作已完成。');if(confirmation.value?.id===id&&confirmation.value.operation===operation)confirmation.value=null;}catch(cause){if(alive&&rows.value.find(row=>row.environment_id===id)?.generation===expectedGeneration){feedback.set(id,(cause as Error).message);if(confirmation.value?.id===id)confirmError.value=(cause as Error).message;}}finally{pending.delete(id);if(alive)void load();}}
/** 物理值保持未采集与零限制的差异。@param key 字段。@param value 实际值。@return 显示文本。 */
function physicalValue(key:string,value:unknown):string{if(value==null)return'未采集';if(typeof value==='boolean')return value?'有':'无';if(key.endsWith('_bytes')&&typeof value==='number')return value===0?'未限制':`${Math.round(value/1024**2)} MiB`;return String(value);}
/** 隐藏页面暂停读取，重新可见后立即回读。@return 无。 */
function visibility():void{clearTimeout(timer);if(!document.hidden)void load();}
watch(()=>route.fullPath,openLinked);
onMounted(()=>{document.addEventListener('visibilitychange',visibility);void connect();});
onUnmounted(()=>{alive=false;generation++;controller?.abort();clearTimeout(timer);document.removeEventListener('visibilitychange',visibility);});
</script>

<template>
  <div v-if="!workspaceTaskAccountId" class="native-runtime runtime-environments">
    <PageHeader title="运行环境" description="查看账号环境状态，管理资源、采集与请求内核。"><template #actions><Button variant="outline" :disabled="loading" @click="connected?load():connect()"><RefreshCw :size="15" />刷新</Button></template></PageHeader>
    <div class="environment-toolbar"><div class="runtime-filter-tabs" aria-label="环境状态筛选"><button v-for="item in counts" :key="item.id" type="button" :aria-pressed="filter===item.id" :class="{active:filter===item.id}" @click="filter=item.id">{{ item.label }}<span>{{ item.count }}</span></button></div><SearchInput v-model="query" label="搜索运行环境" placeholder="搜索账号名称或环境 ID" /></div>
    <p v-if="error" class="runtime-error" role="alert">{{ error }} <Button variant="outline" @click="connected?load():connect()">重试</Button></p><div class="runtime-result-count">显示 {{ filtered.length }} / {{ rows.length }} 个环境 <button v-if="route.query.environment||route.query.gateway_account" type="button" @click="router.replace({name:'environments'})">显示全部环境</button></div>
    <div class="environment-grid"><article v-for="row in filtered" :key="row.environment_id" class="environment-rich" :aria-label="row.name" :data-environment="row.environment_id"><header class="environment-card-head"><span class="environment-avatar"><Box :size="22" /></span><div class="environment-identity"><h2>{{ row.name||'未命名环境' }}<PlatformBadge :platform="row.platform || 'claude_code'" /></h2><div class="environment-meta"><span>{{ row.gateway_account_id!=null?`网关账号 #${row.gateway_account_id}`:row.account_id!=null?`任务账号 #${row.account_id}`:'待提交的授权环境' }}</span><ExecutionNodeBadge class="environment-node" :node="row.node" :status="nodeStatus(row)" :attention="!!row.node && (row.node_observed===false || !row.node.enabled)" /></div></div><span class="environment-status" :class="tone(row)"><i />{{ stateLabel(row) }}</span></header><div class="environment-id"><code>{{ row.environment_id }}</code><span>第 {{ row.generation }} 代</span></div><div class="environment-role-strip"><div v-for="role in roleNames" :key="role.id" :class="{running:row.role_status?.[role.id]==='running'}"><i /><span>{{ role.label }}</span><strong>{{ roles[row.role_status?.[role.id]??'']||'未知' }}</strong></div></div><div class="environment-resources-grid"><div><span>内存配置</span><strong>{{ row.fingerprint?.mem==='unlimited'?'未限制':row.fingerprint?.mem||'未提供' }}</strong></div><div v-for="role in roleNames" :key="role.id"><span>{{ role.label }} CPU</span><strong :title="cpuErrors.get(row.environment_id)">{{ cpuLabel(row,role.id) }}<small v-if="cpu.get(row.environment_id)?.generation===row.generation"> 核</small></strong></div></div><div class="environment-version-line"><span>CLI <strong>{{ row.login_draft?'登录会话管理':row.cli_versions?.join(' / ')||'未安装' }}</strong></span><button type="button" @click="open(row,'kernel')">内核 <strong>{{ row.native_kernel?.management==='platform'?'平台内置':row.native_kernel?.current?.release||'未提供' }}</strong><ArrowRight :size="12" /></button></div><section class="environment-readiness" :class="tone(row)"><div><strong>{{ preparationLabel(row) }}</strong><span class="environment-job">{{ row.login_draft?'登录草稿':row.busy?'CLI 作业执行中':'CLI 作业空闲' }}</span></div><p>293 空闲暖进程 <b>{{ row.native_preparation?.idle_workers??'—' }}</b> / 存活 <b>{{ row.native_preparation?.live_workers??'—' }}</b> · 空闲 PID {{ row.native_preparation?.pid??'未观测' }}</p></section><div class="environment-feature-row"><button type="button" @click="open(row,'resources')"><span>CRIU 加速</span><strong>{{ criuStates[row.criu?.state??'']||'待核对' }}</strong></button><button type="button" @click="open(row,'resources')"><span>内容采集</span><strong>{{ featureLabel(row.content_capture) }}</strong></button></div><button type="button" class="environment-schedule-summary" @click="open(row,'schedule')"><Clock :size="14" /><span>{{ row.run_window?.message||'运行时段待核对' }}<small>{{ row.fingerprint?.tz||'时区待核对' }}</small></span><ArrowRight :size="14" /></button><footer class="environment-card-actions"><button type="button" @click="open(row)"><Box :size="14" />环境详情</button><button type="button" @click="open(row,'resources')"><Settings2 :size="14" />资源与采集</button><button type="button" @click="open(row,'kernel')"><Sparkles :size="14" />请求内核</button><button type="button" @click="open(row,'maintenance')"><ShieldCheck :size="14" />维护</button></footer></article><p v-if="!filtered.length" class="environment-empty">{{ loading?'正在读取环境…':rows.length?'没有匹配的环境，请调整搜索或筛选。':'暂无账号环境。' }}</p></div>
  </div>
  <Dialog :open="!!selected||!!workspaceTaskAccountId" @update:open="setOpen"><DialogContent class="runtime-environment-dialog translate-x-0 translate-y-0" :show-close-button="false" @escape-key-down="event=>{if(editorBusy)event.preventDefault();}" @pointer-down-outside="event=>{if(editorBusy)event.preventDefault();}"><div v-if="selected" class="native-runtime runtime-environment-workspace"><DialogHeader class="runtime-workspace-heading"><DialogTitle>环境管理</DialogTitle><DialogDescription class="sr-only">{{ selected.name }} 的运行状态与环境配置</DialogDescription><button type="button" aria-label="关闭环境详情" :disabled="editorBusy" @click="setOpen(false)"><X :size="17" /></button></DialogHeader><div class="runtime-workspace-scroll"><div class="workspace-panel-context"><span class="environment-avatar"><Box :size="21" /></span><div><strong>{{ selected.name }}</strong><ExecutionNodeBadge compact :node="selected.node" :status="nodeStatus(selected)" :attention="!!selected.node && (selected.node_observed===false || !selected.node.enabled)" /><p>{{ selected.gateway_account_id!=null?`网关账号 #${selected.gateway_account_id}`:selected.account_id!=null?`任务账号 #${selected.account_id}`:'待提交的授权环境' }} · 第 {{ selected.generation }} 代</p></div><span class="environment-status" :class="tone(selected)"><i />{{ stateLabel(selected) }}</span></div><p v-if="selected.login_draft" class="runtime-feedback">登录草稿由原节点管理。请在任务账号页继续登录或完整清理。<a href="/tasks">前往任务账号</a></p><div v-else class="workspace-panel-layout"><nav class="environment-sections" role="tablist" aria-label="环境配置分区"><button v-for="tab in tabs.filter(tab=>selected?.platform!=='antigravity'||tab.id!=='schedule')" :key="tab.id" type="button" role="tab" :aria-selected="activeTab===tab.id" :class="{active:activeTab===tab.id}" :disabled="editorBusy" @click="chooseTab(tab.id)"><component :is="tab.icon" :size="16" />{{ tab.title }}</button></nav><div class="environment-section-content"><header class="workspace-section-heading"><h3>{{ tabs.find(tab=>tab.id===activeTab)?.title }}</h3><p>{{ tabs.find(tab=>tab.id===activeTab)?.note }}</p></header><p v-if="feedback.get(selected.environment_id)" class="runtime-feedback" role="status">{{ feedback.get(selected.environment_id) }}</p>
      <section v-show="activeTab==='overview'" role="tabpanel" aria-label="运行概览"><div class="environment-dialog-stats"><div><span>CPU 额度</span><strong>{{ cpuLabel(selected,'cli') }}</strong></div><div><span>CRIU 加速</span><strong>{{ featureLabel(selected.criu) }}</strong></div><div><span>内容采集</span><strong>{{ featureLabel(selected.content_capture) }}</strong></div></div><div class="workspace-properties"><div v-for="[label,value] in [[selected.platform==='antigravity'?'AGY 版本':'CLI 版本',selected.platform==='antigravity'?selected.agy_runtime?.version||'1.5.9':selected.cli_versions?.join(' / ')||'未安装'],['请求内核',selected.platform==='antigravity'?'AGY 原生':selected.native_kernel?.management==='platform'?'平台内置':selected.native_kernel?.current?.release||'未提供'],['环境状态',`${stateLabel(selected)} · CLI 作业${selected.busy?'执行中':'空闲'}`],['原生准备',preparationLabel(selected)]]" :key="label" class="kv"><span>{{ label }}</span><strong>{{ value }}</strong></div></div><div class="workspace-inline-actions"><Button variant="outline" :disabled="selected.busy||pending.has(selected.environment_id)||selected.role_status?.cli!=='running'" @click="perform(selected.environment_id,'physical')"><RefreshCw :size="14" />刷新物理实测</Button><Button variant="outline" @click="chooseTab('resources')">调整资源与采集<ArrowRight :size="14" /></Button></div><p v-if="selected.credential_ownership" class="runtime-feedback">{{ selected.credential_ownership.message }}<Button v-if="selected.credential_ownership.phase!=='ready'&&['return','attach','authorize'].includes(selected.credential_ownership.direction??'')" variant="outline" :disabled="selected.busy||pending.has(selected.environment_id)" @click="confirmation={id:selected.environment_id,name:selected.name,operation:'cancel-credential-return'}">取消未提交交接</Button></p>
        <details class="runtime-technical"><summary>运行组件与准备详情</summary><div class="workspace-properties"><div v-for="role in roleNames" :key="role.id" class="kv"><span>{{ role.label }}</span><strong>{{ roles[selected.role_status?.[role.id]??'']||'未知' }}</strong></div><div class="kv"><span>内存配置</span><strong>{{ selected.fingerprint?.mem==='unlimited'?'未限制':selected.fingerprint?.mem||'未提供' }}</strong></div><div class="kv"><span>{{ selected.platform==='antigravity'?'AGY 空闲 / 实际进程':'293 空闲暖进程 / 实际进程' }}</span><strong>{{ selected.platform==='antigravity'&&selected.agy_runtime?.workers!=null?selected.agy_runtime.workers-(selected.agy_runtime.active??0):selected.native_preparation?.idle_workers??'未观测' }} / {{ selected.platform==='antigravity'?selected.agy_runtime?.workers??'未观测':selected.native_preparation?.live_workers??'未观测' }}</strong></div><div class="kv"><span>空闲 PID</span><strong>{{ selected.native_preparation?.pid??'未观测' }}</strong></div><div class="kv"><span>最近检查</span><strong>{{ selected.native_preparation?.checked_at_ms?new Date(selected.native_preparation.checked_at_ms).toLocaleString():'未观测' }}</strong></div></div><div v-if="selected.native_preparation?.versions" class="workspace-properties"><div v-for="(value,version) in selected.native_preparation.versions" :key="version" class="kv"><span>{{ version }} 运行时</span><strong>{{ value?prepNames[value.state]||'状态待核对':'未观测' }} · 空闲 {{ value?.idle_workers??'—' }} / 存活 {{ value?.live_workers??'—' }}</strong><small v-if="value?.reason">{{ preparationReasons[value.reason]||'状态待核对' }}</small></div></div><p v-if="selected.native_preparation?.reason">{{ preparationReasons[selected.native_preparation.reason]||'状态待核对' }}</p><p v-if="selected.native_preparation?.adaptive_prewarm!=null">并发备用：{{ selected.native_preparation.adaptive_prewarm?'已启用第二进程补位':'保留一个常驻热进程' }}。</p><Button v-if="selected.request_backend==='native293'&&['failed','unknown','unprepared','sleeping'].includes(selected.native_preparation?.state??'')" variant="outline" :disabled="selected.busy||pending.has(selected.environment_id)||!['ready','stopped'].includes(selected.state)" @click="perform(selected.environment_id,'prepare')">重试原生准备</Button></details>
        <details class="runtime-technical"><summary>环境与物理详情</summary><dl><dt>环境 ID</dt><dd><code>{{ selected.environment_id }}</code></dd><dt>主机名</dt><dd>{{ selected.fingerprint?.hostname||'未提供' }}</dd><dt>设备身份</dt><dd>{{ selected.identity_status||'待核对' }}</dd><dt>语言区域</dt><dd>{{ selected.fingerprint?.lang||'未提供' }}</dd><dt>画像版本</dt><dd>{{ selected.fingerprint?.profile_version??'未提供' }}</dd></dl><template v-if="selected.physical_features"><p>{{ selected.physical_features.message }} · {{ selected.physical_features.observed_at?new Date(selected.physical_features.observed_at*1000).toLocaleString():'未采集' }}</p><div class="runtime-table-scroll"><table class="runtime-physical-table"><thead><tr><th>特征</th><th>保存配置</th><th>容器实测</th><th>对照</th></tr></thead><tbody><tr v-for="field in selected.physical_features.fields" :key="field.key"><th>{{ field.label }}</th><td>{{ field.configured==null?'无对应配置':physicalValue(field.key,field.configured) }}</td><td>{{ physicalValue(field.key,field.observed) }}</td><td>{{ ({match:'一致',mismatch:'有差异',observed:'已采集',unobserved:'未采集',stale:'旧代观察'} as Record<string,string>)[field.status]||'未采集' }}</td></tr></tbody></table></div></template></details>
      </section>
      <section v-if="visited.has('resources')" v-show="activeTab==='resources'" role="tabpanel" aria-label="资源与采集"><EnvironmentResources :key="selected.environment_id" :environment="selected" @refresh="load" @busy="editorBusy=$event" @cpu="acceptCpu(selected!.environment_id,$event)" /></section>
      <section v-if="visited.has('kernel')" v-show="activeTab==='kernel'" role="tabpanel" aria-label="请求内核"><EnvironmentKernel :key="selected.environment_id" :environment="selected" @refresh="load" @busy="editorBusy=$event" /></section>
      <section v-if="visited.has('schedule')" v-show="activeTab==='schedule'" role="tabpanel" aria-label="运行时段"><RunWindowForm v-if="selected.account_id!=null&&selected.run_window" :key="selected.account_id" :account-id="selected.account_id" @saved="load" @busy="editorBusy=$event" /><p v-else>运行窗口尚未提供。</p></section>
      <section v-show="activeTab==='maintenance'" role="tabpanel" aria-label="维护操作"><div v-for="operation in maintenance" :key="operation.id" class="maintenance-option"><div><strong>{{ operation.label }}</strong><p>{{ operation.id==='reprofile'?selected.reprofile_message||operation.note:operation.note }}</p></div><Button :variant="['stop','rebuild'].includes(operation.id)?'destructive':'outline'" :disabled="pending.has(selected.environment_id)||(selected.busy&&!(operation.id==='reconcile'&&selected.reconcile_allowed))||(operation.id==='reprofile'&&!selected.can_reprofile)" @click="confirmError='';confirmation={id:selected.environment_id,name:selected.name,operation:operation.id}">{{ operation.label }}</Button></div></section>
    </div></div></div></div><div v-else class="runtime-local-loading"><DialogHeader><DialogTitle>环境管理</DialogTitle><DialogDescription>{{ loading?'正在读取账号环境…':error||'账号环境暂不可用' }}</DialogDescription></DialogHeader><Button v-if="!loading" variant="outline" @click="connected?load():connect()">重新读取</Button><Button variant="outline" @click="setOpen(false)">关闭</Button></div></DialogContent></Dialog>
  <ConfirmationDialog :open="!!confirmation" :title="maintenance.find(item=>item.id===confirmation?.operation)?.label||'取消未提交交接'" :message="`${confirmation?.name || ''} · 确认在账号空闲时执行此维护操作？持久数据会保留。`" confirm-label="确认操作" :danger="['stop','rebuild'].includes(confirmation?.operation || '')" :busy="!!confirmation && pending.has(confirmation.id)" :error="confirmError" @confirm="confirmation && perform(confirmation.id,confirmation.operation)" @cancel="confirmation=null" />
</template>
